            font-size: 14px;
            font-weight: 500;
            z-index: 7000;
            opacity: 0;
            pointer-events: none;
            transition: opacity 0.25s ease, transform 0.25s ease;
            box-shadow: 0 6px 20px rgba(0,0,0,0.5);
        }

        .toast-msg.show {
            opacity: 1;
            transform: translateX(-50%) translateY(0);
        }

        .more-btn {
            width: 32px;
            height: 32px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            color: var(--text-secondary);
            cursor: pointer;
            transition: background 0.15s ease, color 0.15s ease;
            margin-left: 8px;
            flex-shrink: 0;
        }

        .more-btn:hover {
            background: rgba(255, 255, 255, 0.12);
            color: var(--text-primary);
        }
    </style>
</head>
<body>

    <div id="safariWarning" class="browser-notice" style="display: none;">
        <div class="notice-content">
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M12 2a14.5 14.5 0 000 20 14.5 14.5 0 000-20"/><path d="M2 12h20"/></svg>
            <span>Use <strong>Safari</strong> for full audio format support (.m4a / ALAC)</span>
        </div>
        <button class="notice-close" onclick="document.getElementById('safariWarning').style.display='none';">&times;</button>
    </div>

    <div class="view-container">
        <!-- Library View -->
        <div id="view-library" class="view active">
            <div class="large-header">
                <div class="header-top">
                    <h1>AudioStream</h1>
                </div>
                <div class="header-tabs">
                    <span class="header-tab active" onclick="switchTab('library')">Albums</span>
                    <span class="header-tab" onclick="switchTab('artists')">Artists</span>
                    <span class="header-tab" onclick="switchTab('playlists')">Playlists</span>
                </div>
            </div>
            <div class="album-grid" id="albumGrid"></div>
        </div>

        <!-- Artists View -->
        <div id="view-artists" class="view">
            <div class="large-header">
                <div class="header-top">
                    <h1>Artists</h1>
                </div>
                <div class="header-tabs">
                    <span class="header-tab" onclick="switchTab('library')">Albums</span>
                    <span class="header-tab active" onclick="switchTab('artists')">Artists</span>
                    <span class="header-tab" onclick="switchTab('playlists')">Playlists</span>
                </div>
            </div>
            <div class="album-grid" id="artistGrid"></div>
        </div>

        <!-- Playlists View -->
        <div id="view-playlists" class="view">
            <div class="large-header">
                <div class="header-top">
                    <h1>Playlists</h1>
                </div>
                <div class="header-tabs">
                    <span class="header-tab" onclick="switchTab('library')">Albums</span>
                    <span class="header-tab" onclick="switchTab('artists')">Artists</span>
                    <span class="header-tab active" onclick="switchTab('playlists')">Playlists</span>
                </div>
            </div>
            <div class="album-grid" id="playlistGrid"></div>
        </div>

        <!-- Search View -->
        <div id="view-search" class="view">
            <div class="large-header">
                <div class="header-top">
                    <h1>Search</h1>
                </div>
            </div>
            <div class="search-container">
                <input type="text" class="search-bar" id="searchInput" placeholder="Songs, Artists, Albums...">
            </div>
            <div id="searchResults"></div>
        </div>

        <!-- Settings View -->
        <div id="view-settings" class="view">
            <div class="large-header">
                <div class="header-top">
                    <h1>Settings</h1>
                </div>
            </div>
            
            <div class="settings-group">
                <div class="settings-row">
                    <span class="settings-label">Server Host</span>
                    <span class="settings-value" id="serverInfo">...</span>
                </div>
                <div class="settings-row">
                    <span class="settings-label">Connection Status</span>
                    <span class="settings-value text-accent">● Connected</span>
                </div>
                <div class="settings-row">
                    <span class="settings-label">Total Tracks</span>
                    <span class="settings-value" id="totalSongsCount">0</span>
                </div>
            </div>
            
            <div class="settings-group">
                <div class="settings-row">
                    <span class="settings-label">Custom Music Path</span>
                    <span class="settings-value">/var/mobile/Documents/AudioStreamMusic</span>
                </div>
                <div class="settings-row">
                    <span class="settings-label">iTunes DB Path</span>
                    <span class="settings-value">/var/mobile/Media/iTunes_Control/...</span>
                </div>
            </div>
        </div>
    </div>

    <!-- Detail Modal Overlay -->
    <div class="detail-modal" id="detailModal">
        <div class="modal-header">
            <button class="back-btn" id="closeDetailBtn">
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M15 18l-6-6 6-6"/></svg>
                Back
            </button>
        </div>
        <div class="detail-hero" id="modalHero"></div>
        <div id="modalTrackList"></div>
    </div>

    <!-- Mini Player -->
    <div class="mini-player hidden" id="miniPlayer">
        <div class="mini-art" id="miniArt"></div>
        <div class="mini-info">
            <div class="mini-title" id="miniTitle">Song Title</div>
            <div class="mini-artist" id="miniArtist">Artist</div>
        </div>
        <button class="mini-btn" id="miniPlayBtn">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>
        </button>
    </div>

    <!-- Now Playing Overlay -->
    <div class="now-playing-overlay" id="nowPlayingOverlay">
        <div class="capsule-handle" id="closeNowPlaying"></div>
        <div class="np-content">
            <div class="np-art" id="npArt"></div>
            <div class="np-info">
                <div class="np-title" id="npTitle">Title</div>
                <div class="np-artist" id="npArtist">Artist</div>
            </div>
            
            <div class="np-progress">
                <div class="progress-bar-bg" id="scrubBar">
                    <div class="progress-fill" id="npProgressFill">
                        <div class="progress-knob"></div>
                    </div>
                </div>
                <div class="time-labels">
                    <span id="npCurrentTime">0:00</span>
                    <span id="npDuration">0:00</span>
                </div>
            </div>
            
            <div class="np-controls">
                <button class="np-btn mode-btn" id="npShuffleBtn" title="Shuffle">
                    <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M16 3h5v5M4 20l5-5M21 3l-7.5 7.5M16 21h5v-5M4 4l17 17"/></svg>
                </button>
                <button class="np-btn skip-btn" id="npPrevBtn">
                    <svg width="32" height="32" viewBox="0 0 24 24" fill="currentColor"><path d="M6 6h2v12H6zm3.5 6l8.5 6V6z"/></svg>
                </button>
                <button class="np-btn play-pause-lg" id="npPlayBtn">
                    <svg width="30" height="30" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>
                </button>
                <button class="np-btn skip-btn" id="npNextBtn">
                    <svg width="32" height="32" viewBox="0 0 24 24" fill="currentColor"><path d="M6 18l8.5-6L6 6v12zM16 6v12h2V6h-2z"/></svg>
                </button>
                <button class="np-btn mode-btn" id="npRepeatBtn" title="Repeat">
                    <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M17 1l4 4-4 4M3 11V9a4 4 0 01-4 4H3"/></svg>
                </button>
            </div>
        </div>
    </div>

    <!-- Tab Bar -->
    <div class="tab-bar">
        <div class="tab-item active" onclick="switchTab('library')">
            <svg class="tab-icon" viewBox="0 0 24 24"><path d="M12 3v10.55c-.59-.34-1.27-.55-2-.55-2.21 0-4 1.79-4 4s1.79 4 4 4 4-1.79 4-4V7h4V3h-6z"/></svg>
            <span>Library</span>
        </div>
        <div class="tab-item" onclick="switchTab('search')">
            <svg class="tab-icon" viewBox="0 0 24 24"><path d="M15.5 14h-.79l-.28-.27C15.41 12.59 16 11.11 16 9.5 16 5.91 13.09 3 9.5 3S3 5.91 3 9.5 5.91 16 9.5 16c1.61 0 3.09-.59 4.23-1.57l.27.28v.79l5 4.99L20.49 19l-4.99-5zm-6 0C7.01 14 5 11.99 5 9.5S7.01 5 9.5 5 14 7.01 14 9.5 11.99 14 9.5 14z"/></svg>
            <span>Search</span>
        </div>
        <div class="tab-item" onclick="switchTab('settings')">
            <svg class="tab-icon" viewBox="0 0 24 24"><path d="M19.14 12.94c.04-.3.06-.61.06-.94 0-.32-.02-.64-.07-.94l2.03-1.58c.18-.14.23-.41.12-.61l-1.92-3.32c-.12-.22-.37-.29-.59-.22l-2.39.96c-.5-.38-1.03-.7-1.62-.94l-.36-2.54c-.04-.24-.24-.41-.48-.41h-3.84c-.24 0-.43.17-.47.41l-.36 2.54c-.59.24-1.13.57-1.62.94l-2.39-.96c-.22-.08-.47 0-.59.22L2.74 8.87c-.12.21-.08.47.12.61l2.03 1.58c-.05.3-.09.63-.09.94s.02.64.07.94l-2.03 1.58c-.18.14-.23.41-.12.61l1.92 3.32c.12.22.37.29.59.22l2.39-.96c.5.38 1.03.7 1.62.94l.36 2.54c.05.24.24.41.48.41h3.84c.24 0 .44-.17.47-.41l.36-2.54c.59-.24 1.13-.56 1.62-.94l2.39.96c.22.08.47 0 .59-.22l1.92-3.32c.12-.22.07-.47-.12-.61l-2.01-1.58zM12 15.6c-1.98 0-3.6-1.62-3.6-3.6s1.62-3.6 3.6-3.6 3.6 1.62 3.6 3.6-1.62 3.6-3.6-3.6z"/></svg>
            <span>Settings</span>
        </div>
    </div>

    <audio id="audioElement"></audio>

    <!-- Context Menu -->
    <div id="contextMenu" class="context-menu">
        <div class="context-menu-header">
            <div id="ctxTitle" class="context-menu-title">Item Title</div>
            <div id="ctxSubtitle" class="context-menu-subtitle">Item Type</div>
        </div>
        <div id="ctxDeleteBtn" class="context-menu-item danger">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 6h18M19 6v14a2 2 0 01-2 2H7a2 2 0 01-2-2V6m3 0V4a2 2 0 012-2h4a2 2 0 012 2v2M10 11v6M14 11v6"/></svg>
            Delete
        </div>
    </div>

    <!-- Confirmation Dialog Overlay -->
    <div id="confirmOverlay" class="confirm-overlay">
        <div class="confirm-dialog">
            <div id="confirmTitle" class="confirm-dialog-title">Delete Item</div>
            <div id="confirmMessage" class="confirm-dialog-message">Are you sure?</div>
            <div class="confirm-dialog-actions">
                <button id="confirmCancelBtn" class="btn-confirm-cancel">Cancel</button>
                <button id="confirmDangerBtn" class="btn-confirm-danger">Delete</button>
            </div>
        </div>
    </div>

    <!-- Toast Notification -->
    <div id="toastMsg" class="toast-msg"></div>

    <script>
        let allSongs = [];
        let albums = {};
        let artists = {};
        let playlists = [];
        let queue = [];
        let currentIndex = -1;
        let isPlaying = false;
        let isShuffle = false;
        let repeatMode = 'off';

        const audio = document.getElementById('audioElement');

        function checkBrowserCompatibility() {
            const ua = navigator.userAgent;
            const isSafari = /^((?!chrome|android|crios|fxios|edg).)*safari/i.test(ua);
            if (!isSafari) {
                document.getElementById('safariWarning').style.display = 'flex';
            }
        }

        async function init() {
            checkBrowserCompatibility();
            document.getElementById('serverInfo').innerText = window.location.host;

            try {
                const res = await fetch('/api/songs');
                allSongs = await res.json();
                document.getElementById('totalSongsCount').innerText = allSongs.length;

                const plRes = await fetch('/api/playlists');
                playlists = await plRes.json();

                processSongsIntoAlbums();
                processSongsIntoArtists();
                renderLibrary();
                renderArtists();
                renderPlaylists();
            } catch (e) {
                console.error('Failed to load library', e);
            }

            setupEventListeners();
        }

        function processSongsIntoAlbums() {
            albums = {};
            allSongs.forEach(song => {
                const albName = song.album || "Unknown Album";
                if (!albums[albName]) {
                    albums[albName] = {
                        title: albName,
                        artist: song.artist || "Unknown Artist",
                        songs: [],
                        dateAdded: 0
                    };
                }
                albums[albName].songs.push(song);
                if (song.dateAdded && song.dateAdded > albums[albName].dateAdded) {
                    albums[albName].dateAdded = song.dateAdded;
                }
            });
            Object.values(albums).forEach(alb => {
                alb.songs.sort((a, b) => (a.trackNumber || 0) - (b.trackNumber || 0));
            });
        }

        function processSongsIntoArtists() {
            artists = {};
            allSongs.forEach(song => {
                const artName = song.artist || "Unknown Artist";
                if (!artists[artName]) {
                    artists[artName] = {
                        name: artName,
                        albums: [],
                        songs: []
                    };
                }
                artists[artName].songs.push(song);
                if (!artists[artName].albums.includes(song.album)) {
                    artists[artName].albums.push(song.album);
                }
            });
        }

        let currentCtxTarget = null;

        function showContextMenu(e, type, data) {
            if (e) {
                e.preventDefault();
                e.stopPropagation();
            }
            
            currentCtxTarget = { type, data };
            const menu = document.getElementById('contextMenu');
            const titleEl = document.getElementById('ctxTitle');
            const subtitleEl = document.getElementById('ctxSubtitle');
            
            if (type === 'album') {
                titleEl.textContent = data.title;
                subtitleEl.textContent = `Album • ${data.artist}`;
            } else if (type === 'song') {
                titleEl.textContent = data.title;
                subtitleEl.textContent = `Song • ${data.artist}`;
            }
            
            menu.style.display = 'block';
            
            const menuWidth = 220;
            const menuHeight = menu.offsetHeight || 100;
            let x = e ? e.clientX : window.innerWidth / 2;
            let y = e ? e.clientY : window.innerHeight / 2;
            
            if (x + menuWidth > window.innerWidth) {
                x = window.innerWidth - menuWidth - 12;
            }
            if (y + menuHeight > window.innerHeight) {
                y = window.innerHeight - menuHeight - 12;
            }
            if (x < 12) x = 12;
            if (y < 12) y = 12;
            
            menu.style.left = x + 'px';
            menu.style.top = y + 'px';
        }

        function hideContextMenu() {
            const menu = document.getElementById('contextMenu');
            if (menu) menu.style.display = 'none';
        }

        function showToast(msg) {
            const t = document.getElementById('toastMsg');
            if (!t) return;
            t.textContent = msg;
            t.classList.add('show');
            setTimeout(() => t.classList.remove('show'), 2500);
        }

        document.addEventListener('click', hideContextMenu);
        document.addEventListener('scroll', hideContextMenu, true);
        window.addEventListener('resize', hideContextMenu);

        const ctxDelBtn = document.getElementById('ctxDeleteBtn');
        if (ctxDelBtn) {
            ctxDelBtn.onclick = (e) => {
                e.stopPropagation();
                hideContextMenu();
                if (!currentCtxTarget) return;
                
                const { type, data } = currentCtxTarget;
                const overlay = document.getElementById('confirmOverlay');
                const title = document.getElementById('confirmTitle');
                const msg = document.getElementById('confirmMessage');
                
                if (type === 'album') {
                    title.textContent = 'Delete Album';
                    msg.textContent = `Are you sure you want to delete "${data.title}" by ${data.artist}? This will permanently delete all tracks in this album from your device.`;
                } else {
                    title.textContent = 'Delete Song';
                    msg.textContent = `Are you sure you want to delete "${data.title}" by ${data.artist}? This will permanently delete this file from your device.`;
                }
                
                overlay.classList.add('active');
            };
        }

        const cancelBtn = document.getElementById('confirmCancelBtn');
        if (cancelBtn) {
            cancelBtn.onclick = () => {
                document.getElementById('confirmOverlay').classList.remove('active');
            };
        }

        const dangerBtn = document.getElementById('confirmDangerBtn');
        if (dangerBtn) {
            dangerBtn.onclick = async () => {
                document.getElementById('confirmOverlay').classList.remove('active');
                if (!currentCtxTarget) return;
                
                const { type, data } = currentCtxTarget;
                let payload = {};
                if (type === 'album') {
                    payload = { type: 'album', album: data.title, artist: data.artist };
                } else {
                    payload = { type: 'song', id: data.id, persistentId: String(data.persistentId) };
                }
                
                try {
                    const res = await fetch('/api/delete', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify(payload)
                    });
                    const result = await res.json();
                    if (result.success) {
                        showToast(type === 'album' ? 'Album deleted' : 'Song deleted');
                        handlePostDelete(type, data);
                    } else {
                        showToast(result.error || 'Failed to delete item');
                    }
                } catch (err) {
                    console.error('Delete error:', err);
                    showToast('Error deleting item');
                }
            };
        }

        function handlePostDelete(type, data) {
            if (type === 'album') {
                allSongs = allSongs.filter(s => !(s.album.toLowerCase() === data.title.toLowerCase() && s.artist.toLowerCase() === data.artist.toLowerCase()));
            } else if (type === 'song') {
                allSongs = allSongs.filter(s => String(s.id) !== String(data.id));
                if (window.currentModalSongs) {
                    window.currentModalSongs = window.currentModalSongs.filter(s => String(s.id) !== String(data.id));
                }
            }
            
            processSongsIntoAlbums();
            processSongsIntoArtists();
            
            renderLibrary();
            renderArtists();
            renderPlaylists();
            
            const searchInput = document.getElementById('searchInput');
            if (searchInput && searchInput.value) {
                renderSearch(searchInput.value);
            }
            
            const detailModal = document.getElementById('detailModal');
            if (detailModal && detailModal.classList.contains('active')) {
                if (type === 'album' && currentCtxTarget && currentCtxTarget.data.title === data.title) {
                    detailModal.classList.remove('active');
                } else if (window.currentModalSongs) {
                    if (window.currentModalSongs.length === 0) {
                        detailModal.classList.remove('active');
                    } else {
                        const list = document.getElementById('modalTrackList');
                        renderTrackListInto(list, window.currentModalSongs);
                    }
                }
            }
        }

        function renderLibrary() {
            const grid = document.getElementById('albumGrid');
            grid.innerHTML = '';
            
            Object.values(albums).sort((a, b) => {
                const dateA = a.dateAdded || 0;
                const dateB = b.dateAdded || 0;
                if (dateB !== dateA) {
                    return dateB - dateA;
                }
                return a.title.localeCompare(b.title);
            }).forEach(album => {
                const card = document.createElement('div');
                card.className = 'album-card';
                card.onclick = () => openAlbumDetail(album);
                card.oncontextmenu = (e) => showContextMenu(e, 'album', album);

                const pid = album.songs[0].persistentId;
                const artUrl = '/artwork/' + pid;

                card.innerHTML = `
                    <div class="album-art">
                        <img src="${artUrl}" onerror="this.style.display='none'; this.nextElementSibling.style.display='flex';" onload="this.style.display='block'; this.nextElementSibling.style.display='none';">
                        <div class="album-art-placeholder" style="display:none;">
                            ${escapeHtml(album.title.charAt(0).toUpperCase())}
                        </div>
                    </div>
                    <div class="album-title">${escapeHtml(album.title)}</div>
                    <div class="album-artist">${escapeHtml(album.artist)}</div>
                `;
                grid.appendChild(card);
            });
        }

        function renderArtists() {
            const grid = document.getElementById('artistGrid');
            grid.innerHTML = '';

            Object.values(artists).sort((a,b) => a.name.localeCompare(b.name)).forEach(artist => {
                const card = document.createElement('div');
                card.className = 'album-card';
                card.onclick = () => openArtistDetail(artist);

                const pid = artist.songs[0].persistentId;
                const artUrl = '/artwork/' + pid;

                card.innerHTML = `
                    <div class="album-art" style="border-radius: 50%;">
                        <img src="${artUrl}" onerror="this.style.display='none'; this.nextElementSibling.style.display='flex';" onload="this.style.display='block'; this.nextElementSibling.style.display='none';">
                        <div class="album-art-placeholder" style="display:none;">
                            ${escapeHtml(artist.name.charAt(0).toUpperCase())}
                        </div>
                    </div>
                    <div class="album-title" style="text-align:center;">${escapeHtml(artist.name)}</div>
                    <div class="album-artist" style="text-align:center;">${artist.songs.length} Tracks</div>
                `;
                grid.appendChild(card);
            });
        }

        function renderPlaylists() {
            const grid = document.getElementById('playlistGrid');
            grid.innerHTML = '';

            const gradients = [
                'linear-gradient(135deg, #fa2d48, #ff758c)',
                'linear-gradient(135deg, #4776E6, #8E54E9)',
                'linear-gradient(135deg, #FF512F, #DD2476)',
                'linear-gradient(135deg, #00b09b, #96c93d)',
                'linear-gradient(135deg, #8A2387, #E94057, #F27121)'
            ];

            playlists.forEach((playlist, idx) => {
                const card = document.createElement('div');
                card.className = 'album-card';
                card.onclick = () => openPlaylistDetail(playlist);

                const grad = gradients[idx % gradients.length];
                let imgHtml = '';
                if (playlist.songIds.length > 0) {
                    const firstSong = allSongs.find(s => String(s.id) === String(playlist.songIds[0]));
                    if (firstSong) {
                        imgHtml = `<img src="/artwork/${firstSong.persistentId}" onerror="this.style.display='none';" onload="this.style.display='block';">`;
                    }
                }

                card.innerHTML = `
                    <div class="album-art" style="background: ${grad};">
                        ${imgHtml}
                        <div class="album-art-placeholder" style="${imgHtml ? 'display:none;' : 'display:flex;'} background: transparent; color: white;">
                            ${escapeHtml(playlist.name.charAt(0).toUpperCase())}
                        </div>
                    </div>
                    <div class="album-title">${escapeHtml(playlist.name)}</div>
                    <div class="album-artist">${playlist.songIds.length} Tracks</div>
                `;
                grid.appendChild(card);
            });
        }

        function renderSearch(query = '') {
            const container = document.getElementById('searchResults');
            container.innerHTML = '';

            if (!query.trim()) return;

            const q = query.toLowerCase();
            const matches = allSongs.filter(s => 
                (s.title && s.title.toLowerCase().includes(q)) || 
                (s.artist && s.artist.toLowerCase().includes(q)) || 
                (s.album && s.album.toLowerCase().includes(q))
            );

            if (matches.length === 0) {
                container.innerHTML = '<div style="padding: 30px; color: var(--text-secondary); text-align: center; font-size: 15px;">No results found</div>';
                return;
            }

            matches.forEach(song => {
                const div = document.createElement('div');
                div.className = 'list-item';
                div.onclick = () => playSingleSong(song, matches);
                div.oncontextmenu = (e) => showContextMenu(e, 'song', song);
                div.innerHTML = `
                    <div class="list-thumb">
                        <img src="/artwork/${song.persistentId}" onerror="this.parentElement.style.backgroundColor='#2c2c2e'; this.style.display='none';">
                    </div>
                    <div class="list-info">
                        <div class="list-title">${escapeHtml(song.title)}</div>
                        <div class="list-subtitle">${escapeHtml(song.artist)} • ${escapeHtml(song.album)}</div>
                    </div>
                    <div class="list-duration">${song.durationFormatted || ''}</div>
                `;
                const moreBtn = document.createElement('div');
                moreBtn.className = 'more-btn';
                moreBtn.innerHTML = '<svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor"><path d="M12 8c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm0 2c-1.1 0-2 .9-2 2s.9 2 2 2 2-.9 2-2-.9-2-2-2zm0 6c-1.1 0-2 .9-2 2s.9 2 2 2 2-.9 2-2-.9-2-2-2z"/></svg>';
                moreBtn.onclick = (e) => {
                    e.stopPropagation();
                    showContextMenu(e, 'song', song);
                };
                div.appendChild(moreBtn);
                container.appendChild(div);
            });
        }

        function openAlbumDetail(album) {
            const hero = document.getElementById('modalHero');
            const list = document.getElementById('modalTrackList');
            const pid = album.songs[0].persistentId;

            hero.innerHTML = `
                <div class="detail-art">
                    <img src="/artwork/${pid}" onerror="this.parentElement.style.backgroundColor='#2c2c2e'; this.style.display='none';">
                </div>
                <div class="detail-title">${escapeHtml(album.title)}</div>
                <div class="detail-subtitle">${escapeHtml(album.artist)} • ${album.songs.length} Tracks</div>
                <div class="action-buttons">
                    <button class="btn-primary" onclick="playQueue(currentModalSongs, 0)">
                        <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>
                        Play
                    </button>
                    <button class="btn-secondary" onclick="playQueue(shuffleArray([...currentModalSongs]), 0)">
                        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M16 3h5v5M4 20l5-5M21 3l-7.5 7.5M16 21h5v-5M4 4l17 17"/></svg>
                        Shuffle
                    </button>
                </div>
            `;

            window.currentModalSongs = album.songs;
            renderTrackListInto(list, album.songs);
            document.getElementById('detailModal').classList.add('active');
        }

        function openArtistDetail(artist) {
            const hero = document.getElementById('modalHero');
            const list = document.getElementById('modalTrackList');
            const pid = artist.songs[0].persistentId;

            hero.innerHTML = `
                <div class="detail-art" style="border-radius: 50%;">
                    <img src="/artwork/${pid}" onerror="this.parentElement.style.backgroundColor='#2c2c2e'; this.style.display='none';">
                </div>
                <div class="detail-title">${escapeHtml(artist.name)}</div>
                <div class="detail-subtitle">${artist.songs.length} Tracks • ${artist.albums.length} Albums</div>
                <div class="action-buttons">
                    <button class="btn-primary" onclick="playQueue(currentModalSongs, 0)">
                        <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>
                        Play
                    </button>
                    <button class="btn-secondary" onclick="playQueue(shuffleArray([...currentModalSongs]), 0)">
                        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M16 3h5v5M4 20l5-5M21 3l-7.5 7.5M16 21h5v-5M4 4l17 17"/></svg>
                        Shuffle
                    </button>
                </div>
            `;

            window.currentModalSongs = artist.songs;
            renderTrackListInto(list, artist.songs);
            document.getElementById('detailModal').classList.add('active');
        }

        function openPlaylistDetail(playlist) {
            const hero = document.getElementById('modalHero');
            const list = document.getElementById('modalTrackList');

            const playlistSongs = [];
            playlist.songIds.forEach(id => {
                const s = allSongs.find(song => String(song.id) === String(id));
                if (s) playlistSongs.push(s);
            });

            let pid = playlistSongs[0] ? playlistSongs[0].persistentId : '';

            hero.innerHTML = `
                <div class="detail-art">
                    ${pid ? `<img src="/artwork/${pid}" onerror="this.parentElement.style.backgroundColor='#2c2c2e'; this.style.display='none';">` : ''}
                </div>
                <div class="detail-title">${escapeHtml(playlist.name)}</div>
                <div class="detail-subtitle">${playlistSongs.length} Tracks</div>
                <div class="action-buttons">
                    <button class="btn-primary" onclick="playQueue(currentModalSongs, 0)">
                        <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>
                        Play
                    </button>
                    <button class="btn-secondary" onclick="playQueue(shuffleArray([...currentModalSongs]), 0)">
                        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M16 3h5v5M4 20l5-5M21 3l-7.5 7.5M16 21h5v-5M4 4l17 17"/></svg>
                        Shuffle
                    </button>
                </div>
            `;

            window.currentModalSongs = playlistSongs;
            renderTrackListInto(list, playlistSongs);
            document.getElementById('detailModal').classList.add('active');
        }

        function renderTrackListInto(container, songList) {
            container.innerHTML = '';
            songList.forEach((song, idx) => {
                const div = document.createElement('div');
                div.className = 'list-item';
                div.onclick = () => playQueue(songList, idx);
                div.oncontextmenu = (e) => showContextMenu(e, 'song', song);
                div.innerHTML = `
                    <div style="width: 28px; text-align: center; color: var(--text-secondary); font-size: 14px; margin-right: 12px; font-variant-numeric: tabular-nums;">
                        ${song.trackNumber || (idx + 1)}
                    </div>
                    <div class="list-info">
                        <div class="list-title">${escapeHtml(song.title)}</div>
                        <div class="list-subtitle">${escapeHtml(song.artist)} • ${escapeHtml(song.album)}</div>
                    </div>
                    <div class="list-duration">${song.durationFormatted || ''}</div>
                `;
                const moreBtn = document.createElement('div');
                moreBtn.className = 'more-btn';
                moreBtn.innerHTML = '<svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor"><path d="M12 8c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm0 2c-1.1 0-2 .9-2 2s.9 2 2 2 2-.9 2-2-.9-2-2-2zm0 6c-1.1 0-2 .9-2 2s.9 2 2 2 2-.9 2-2-.9-2-2-2z"/></svg>';
                moreBtn.onclick = (e) => {
                    e.stopPropagation();
                    showContextMenu(e, 'song', song);
                };
                div.appendChild(moreBtn);
                container.appendChild(div);
            });
        }

        function playQueue(songList, startIndex = 0) {
            if (!songList || songList.length === 0) return;
            queue = [...songList];
            playTrackAtIndex(startIndex);
            showNowPlaying();
        }

        function playSingleSong(song, matchGroup = []) {
            queue = matchGroup.length > 0 ? matchGroup : [song];
            const idx = queue.findIndex(s => String(s.id) === String(song.id));
            playTrackAtIndex(idx >= 0 ? idx : 0);
            showNowPlaying();
        }

        function playTrackAtIndex(index) {
            if (index < 0 || index >= queue.length) return;
            currentIndex = index;
            const song = queue[currentIndex];
            if (!song) return;

            const encodedPath = song.filename.split('/').map(encodeURIComponent).join('/');
            audio.src = '/music/' + encodedPath;
            audio.play().then(() => {
                isPlaying = true;
                updateUIState();
            }).catch(e => console.log('Playback error:', e));

            updateMiniPlayer(song);
            updateFullPlayer(song);

            document.getElementById('miniPlayer').classList.remove('hidden');

            if ('mediaSession' in navigator) {
                navigator.mediaSession.metadata = new MediaMetadata({
                    title: song.title,
                    artist: song.artist,
                    album: song.album,
                    artwork: [
                        { src: '/artwork/' + song.persistentId, sizes: '512x512', type: 'image/jpeg' }
                    ]
                });
            }
        }

        function togglePlay() {
            if (audio.paused) {
                audio.play();
                isPlaying = true;
            } else {
                audio.pause();
                isPlaying = false;
            }
            updateUIState();
        }

        function nextTrack() {
            if (repeatMode === 'one') {
                audio.currentTime = 0;
                audio.play();
                return;
            }
            if (currentIndex < queue.length - 1) {
                playTrackAtIndex(currentIndex + 1);
            } else if (repeatMode === 'all') {
                playTrackAtIndex(0);
            }
        }

        function prevTrack() {
            if (audio.currentTime > 3) {
                audio.currentTime = 0;
            } else if (currentIndex > 0) {
                playTrackAtIndex(currentIndex - 1);
            }
        }

        function toggleShuffle() {
            isShuffle = !isShuffle;
            document.getElementById('npShuffleBtn').classList.toggle('active', isShuffle);
            if (isShuffle && queue.length > 1) {
                const current = queue[currentIndex];
                const rest = queue.filter((_, i) => i !== currentIndex);
                queue = [current, ...shuffleArray(rest)];
                currentIndex = 0;
            }
        }

        function toggleRepeat() {
            if (repeatMode === 'off') repeatMode = 'all';
            else if (repeatMode === 'all') repeatMode = 'one';
            else repeatMode = 'off';

            const btn = document.getElementById('npRepeatBtn');
            btn.classList.toggle('active', repeatMode !== 'off');
            btn.style.opacity = repeatMode === 'one' ? '1.0' : (repeatMode === 'all' ? '1.0' : '0.6');
        }

        function shuffleArray(arr) {
            for (let i = arr.length - 1; i > 0; i--) {
                const j = Math.floor(Math.random() * (i + 1));
                [arr[i], arr[j]] = [arr[j], arr[i]];
            }
            return arr;
        }

        function updateUIState() {
            const playIcon = '<svg width="24" height="24" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>';
            const pauseIcon = '<svg width="24" height="24" viewBox="0 0 24 24" fill="currentColor"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg>';

            document.getElementById('miniPlayBtn').innerHTML = isPlaying ? pauseIcon : playIcon;
            document.getElementById('npPlayBtn').innerHTML = isPlaying ? pauseIcon : playIcon;
        }

        function updateMiniPlayer(song) {
            document.getElementById('miniTitle').innerText = song.title;
            document.getElementById('miniArtist').innerText = song.artist;
            document.getElementById('miniArt').innerHTML = `<img src="/artwork/${song.persistentId}" onerror="this.style.display='none';">`;
        }

        function updateFullPlayer(song) {
            document.getElementById('npTitle').innerText = song.title;
            document.getElementById('npArtist').innerText = song.artist;
            document.getElementById('npArt').innerHTML = `<img src="/artwork/${song.persistentId}" onerror="this.style.display='none';">`;
        }

        window.switchTab = function(tabName) {
            document.querySelectorAll('.view').forEach(el => el.classList.remove('active'));
            document.querySelectorAll('.tab-item').forEach(el => el.classList.remove('active'));
            document.querySelectorAll('.header-tab').forEach(el => el.classList.remove('active'));

            document.getElementById('view-' + tabName).classList.add('active');

            const tabs = ['library', 'search', 'settings'];
            const idx = tabs.indexOf(tabName);
            if (idx !== -1) {
                document.querySelectorAll('.tab-item')[idx].classList.add('active');
            }

            const topTabs = document.querySelectorAll('#view-' + tabName + ' .header-tab');
            topTabs.forEach(t => {
                if (t.innerText.toLowerCase().includes(tabName)) t.classList.add('active');
            });
        };

        function showNowPlaying() {
            document.getElementById('nowPlayingOverlay').classList.add('visible');
        }

        function hideNowPlaying() {
            document.getElementById('nowPlayingOverlay').classList.remove('visible');
        }

        function escapeHtml(str) {
            const div = document.createElement('div');
            div.textContent = str || '';
            return div.innerHTML;
        }

        function formatTime(s) {
            if (isNaN(s) || !s) return "0:00";
            const m = Math.floor(s / 60);
            const sec = Math.floor(s % 60);
            return m + ':' + sec.toString().padStart(2, '0');
        }

        function setupEventListeners() {
            document.getElementById('searchInput').addEventListener('input', (e) => {
                renderSearch(e.target.value);
            });

            audio.addEventListener('timeupdate', () => {
                if (isScrubbing) return;
                const pct = (audio.currentTime / (audio.duration || 1)) * 100;
                document.getElementById('npProgressFill').style.width = pct + '%';
                document.getElementById('npCurrentTime').innerText = formatTime(audio.currentTime);
                document.getElementById('npDuration').innerText = formatTime(audio.duration);
            });

            audio.addEventListener('ended', nextTrack);

            document.getElementById('miniPlayer').addEventListener('click', (e) => {
                if (!e.target.closest('#miniPlayBtn')) showNowPlaying();
            });

            document.getElementById('closeNowPlaying').onclick = hideNowPlaying;
            document.getElementById('closeDetailBtn').onclick = () => {
                document.getElementById('detailModal').classList.remove('active');
            };

            document.getElementById('miniPlayBtn').onclick = (e) => {
                e.stopPropagation();
                togglePlay();
            };

            document.getElementById('npPlayBtn').onclick = togglePlay;
            document.getElementById('npNextBtn').onclick = nextTrack;
            document.getElementById('npPrevBtn').onclick = prevTrack;
            document.getElementById('npShuffleBtn').onclick = toggleShuffle;
            document.getElementById('npRepeatBtn').onclick = toggleRepeat;

            if ('mediaSession' in navigator) {
                navigator.mediaSession.setActionHandler('play', togglePlay);
                navigator.mediaSession.setActionHandler('pause', togglePlay);
                navigator.mediaSession.setActionHandler('nexttrack', nextTrack);
                navigator.mediaSession.setActionHandler('previoustrack', prevTrack);
            }

            const scrubBar = document.getElementById('scrubBar');
            let isScrubbing = false;

            const updateScrub = (clientX) => {
                const rect = scrubBar.getBoundingClientRect();
                let pct = (clientX - rect.left) / rect.width;
                pct = Math.max(0, Math.min(1, pct));
                document.getElementById('npProgressFill').style.width = (pct * 100) + '%';
                if (audio.duration) {
                    document.getElementById('npCurrentTime').innerText = formatTime(pct * audio.duration);
                }
                return pct;
            };

            const startScrub = (e) => {
                isScrubbing = true;
                const clientX = e.type.includes('touch') ? e.touches[0].clientX : e.clientX;
                updateScrub(clientX);
            };

            const moveScrub = (e) => {
                if (!isScrubbing) return;
                const clientX = e.type.includes('touch') ? e.touches[0].clientX : e.clientX;
                updateScrub(clientX);
            };

            const endScrub = (e) => {
                if (!isScrubbing) return;
                const clientX = e.type.includes('touch') ? e.changedTouches[0].clientX : e.clientX;
                const pct = updateScrub(clientX);
                if (audio.duration) {
                    audio.currentTime = pct * audio.duration;
                }
                isScrubbing = false;
            };

            scrubBar.addEventListener('mousedown', startScrub);
            document.addEventListener('mousemove', moveScrub);
            document.addEventListener('mouseup', endScrub);
            scrubBar.addEventListener('touchstart', startScrub, {passive: true});
            document.addEventListener('touchmove', moveScrub, {passive: true});
            document.addEventListener('touchend', endScrub);
        }

        init();
    </script>
</body>
</html>
